INSERT INTO `perf_instrumen` (`id`, `periode_id`, `kode`, `kategori`, `target_jabatan`, `target_dinilai`, `pertanyaan`, `urutan`, `bobot`, `is_manual`, `tipe_jawaban`, `skor_ya`, `skor_tidak`, `status`, `created_at`) VALUES
(1, 0, 'P17794412810', 'Kompetensi Pedagogik', 'Kepala Sekolah', 'Semua', 'Guru mampu mengelola pembelajaran dengan baik.', 0, 1.00, 0, 'angka', 100.00, 0.00, 1, '2026-05-22 09:14:41'),
(2, 0, 'P17794412841', 'Kompetensi Kepribadian', 'Kepala Sekolah', 'Semua', 'Guru bertindak sesuai dengan norma agama dan hukum.', 0, 1.00, 0, 'angka', 100.00, 0.00, 1, '2026-05-22 09:14:44'),
(3, 0, 'P17794420100', 'Pedagogik', 'Kepala Sekolah,Guru', 'Semua', 'Saya secara konsisten menyiapkan materi yang berbeda atau memberikan pendampingan khusus bagi siswa yang memiliki kecepatan belajar berbeda di kelas', 0, 1.00, 0, 'angka', 100.00, 0.00, 1, '2026-05-22 09:26:50'),
(4, 0, 'P17794420101', 'Pedagogik', 'Kepala Sekolah,Guru', 'Semua', 'Saya mampu beralih ke metode mengajar konvensional secara kreatif saat fasilitas digital (LCD/Internet) rusak mendadak agar kelas tetap efektif.', 0, 1.00, 0, 'angka', 100.00, 0.00, 1, '2026-05-22 09:26:50'),
(5, 0, 'P17794420102', 'Pedagogik', 'Kepala Sekolah,Guru', 'Semua', 'Saya menggunakan teknik bertanya atau pemicu diskusi yang mendorong siswa pasif untuk berani berpendapat di dalam kelas.', 0, 1.00, 0, 'angka', 100.00, 0.00, 1, '2026-05-22 09:26:50'),
(6, 0, 'P17794420103', 'Pedagogik', 'Kepala Sekolah,Guru', 'Semua', 'Saya selalu menyampaikan tujuan pembelajaran dan kegunaan materi tersebut dalam kehidupan nyata di awal sesi agar siswa termotivasi.', 0, 1.00, 0, 'angka', 100.00, 0.00, 1, '2026-05-22 09:26:50'),
(7, 0, 'P17794420104', 'Pedagogik', 'Kepala Sekolah,Guru', 'Semua', 'Saya mampu mengendalikan suasana kelas saat perpindahan aktivitas (transisi) dengan instruksi yang tenang namun tetap dipatuhi siswa.', 0, 1.00, 0, 'angka', 100.00, 0.00, 1, '2026-05-22 09:26:50'),
(8, 0, 'P17794420105', 'Pedagogik', 'Kepala Sekolah,Guru', 'Semua', 'Saya memberikan catatan perbaikan yang spesifik dan bersifat membangun pada setiap hasil pekerjaan siswa secara rutin.', 0, 1.00, 0, 'angka', 100.00, 0.00, 1, '2026-05-22 09:26:50'),
(9, 0, 'P17794420106', 'Pedagogik', 'Kepala Sekolah,Guru', 'Semua', 'Saya memanfaatkan lingkungan sekolah (taman/perpustakaan) sebagai tempat belajar alternatif untuk mengatasi kejenuhan siswa di dalam kelas.', 0, 1.00, 0, 'angka', 100.00, 0.00, 1, '2026-05-22 09:26:50'),
(10, 0, 'P17794420107', 'Pedagogik', 'Kepala Sekolah,Guru', 'Semua', 'Saya melakukan penilaian proses melalui observasi perilaku dan keaktifan siswa untuk melengkapi hasil penilaian ujian tertulis.', 0, 1.00, 0, 'angka', 100.00, 0.00, 1, '2026-05-22 09:26:50'),
(11, 0, 'P17794420108', 'Pedagogik', 'Kepala Sekolah,Guru', 'Semua', 'Saya menyisihkan waktu di akhir jam pelajaran untuk menanyakan kesulitan siswa sebagai bahan refleksi dan perbaikan mengajar saya esok hari.', 0, 1.00, 0, 'angka', 100.00, 0.00, 1, '2026-05-22 09:26:50'),
(12, 0, 'P17794420109', 'Pedagogik', 'Kepala Sekolah,Guru', 'Semua', 'Saya menyajikan berbagai media belajar (visual/audio/praktik) untuk mengakomodasi keberagaman gaya belajar siswa di kelas.', 0, 1.00, 0, 'angka', 100.00, 0.00, 1, '2026-05-22 09:26:50'),
(13, 0, 'P177944201010', 'Kepribadian', 'Kepala Sekolah,Guru', 'Semua', 'Saya hadir di kelas tepat waktu dan mengakhiri pelajaran sesuai jadwal yang telah ditetapkan oleh sekolah.', 0, 1.00, 0, 'angka', 100.00, 0.00, 1, '2026-05-22 09:26:50'),
(14, 0, 'P177944201011', 'Kepribadian', 'Kepala Sekolah,Guru', 'Semua', 'Saya berpakaian rapi, bersih, dan sesuai dengan norma kesopanan sekolah untuk memberikan teladan yang baik bagi siswa.', 0, 1.00, 0, 'angka', 100.00, 0.00, 1, '2026-05-22 09:26:50'),
(15, 0, 'P177944201012', 'Kepribadian', 'Kepala Sekolah,Guru', 'Semua', 'Saya tetap tenang dan mengendalikan emosi dengan baik saat menghadapi perilaku siswa yang memancing amarah atau kekesalan.', 0, 1.00, 0, 'angka', 100.00, 0.00, 1, '2026-05-22 09:26:50'),
(16, 0, 'P177944201013', 'Kepribadian', 'Kepala Sekolah,Guru', 'Semua', 'Saya menyajikan data nilai dan kehadiran siswa secara jujur, transparan, dan objektif tanpa melakukan rekayasa apa pun.', 0, 1.00, 0, 'angka', 100.00, 0.00, 1, '2026-05-22 09:26:50'),
(17, 0, 'P177944201014', 'Kepribadian', 'Kepala Sekolah,Guru', 'Semua', 'Saya menyelesaikan tugas tambahan atau kepanitiaan sekolah dengan tuntas dan tepat waktu tanpa perlu diingatkan berulang kali oleh pimpinan.', 0, 1.00, 0, 'angka', 100.00, 0.00, 1, '2026-05-22 09:26:50'),
