(6826, 6, 'P178081115411', 'Sosial', 'IT-Support', 'Diri Sendiri', 'Saat membimbing rekan kerja yang kurang mahir teknologi, saya menggunakan bahasa yang sederhana dan sangat sabar hingga rekan tersebut benar-benar paham.', 0, 1.00, 0, 'angka', 100.00, 0.00, 1, '2026-06-07 05:45:54'),
(6827, 6, 'P178081115412', 'Sosial', 'IT-Support', 'Diri Sendiri', 'saya mampu menjelaskan penyebab gangguan internet dengan cara yang logis dan mudah dimengerti oleh orang awam.', 0, 1.00, 0, 'angka', 100.00, 0.00, 1, '2026-06-07 05:45:54'),
(6828, 6, 'P178081115413', 'Sosial', 'IT-Support', 'Diri Sendiri', 'saya memberikan pelayanan perbaikan secara adil kepada seluruh unit kerja berdasarkan tingkat urgensi, bukan karena kedekatan pribadi.', 0, 1.00, 0, 'angka', 100.00, 0.00, 1, '2026-06-07 05:45:54'),
