(7188, 6, 'P178081148023', 'Sosial ', 'Wakil Kepala Sekolah', 'Teman Sejawat', 'Dalam rapat dewan guru, rekan guru mampu menyampaikan pendapat atau kritik tanpa menyinggung perasaan orang lain.', 0, 1.00, 0, 'angka', 100.00, 0.00, 1, '2026-06-07 05:51:20'),
(7189, 6, 'P178081148024', 'Sosial ', 'Wakil Kepala Sekolah', 'Teman Sejawat', 'Rekan guru menunjukkan sikap inklusif dan tidak pernah membedakan perlakuannya terhadap rekan sejawat dari latar belakang yang berbeda.', 0, 1.00, 0, 'angka', 100.00, 0.00, 1, '2026-06-07 05:51:20'),
(7190, 6, 'P178081148025', 'Sosial ', 'Wakil Kepala Sekolah', 'Teman Sejawat', 'Saat ada rekan yang sakit atau tertimpa musibah, rekan guru menjadi salah satu yang paling cepat berinisiatif memberikan dukungan atau bantuan.', 0, 1.00, 0, 'angka', 100.00, 0.00, 1, '2026-06-07 05:51:20'),
(7191, 6, 'P178081148026', 'Sosial ', 'Wakil Kepala Sekolah', 'Teman Sejawat', 'Rekan guru mau mendengarkan masukan atau saran terkait pekerjaannya tanpa merasa tersinggung atau defensif.', 0, 1.00, 0, 'angka', 100.00, 0.00, 1, '2026-06-07 05:51:20'),
(7192, 6, 'P178081148027', 'Sosial ', 'Wakil Kepala Sekolah', 'Teman Sejawat', 'Saat terjadi perbedaan pendapat di antara guru, rekan guru sering menjadi penengah yang berupaya mencari jalan keluar terbaik.', 0, 1.00, 0, 'angka', 100.00, 0.00, 1, '2026-06-07 05:51:20'),
(7193, 6, 'P178081148028', 'Sosial ', 'Wakil Kepala Sekolah', 'Teman Sejawat', 'Rekan guru aktif berpartisipasi dalam kegiatan sosial sekolah di luar jam mengajar (seperti kerja bakti atau acara kebersamaan).', 0, 1.00, 0, 'angka', 100.00, 0.00, 1, '2026-06-07 05:51:20'),
(7194, 6, 'P178081148029', 'Sosial ', 'Wakil Kepala Sekolah', 'Teman Sejawat', 'Rekan guru mampu menyampaikan informasi dari sekolah kepada masyarakat atau wali murid secara jelas dan santun saat bertemu.', 0, 1.00, 0, 'angka', 100.00, 0.00, 1, '2026-06-07 05:51:20'),
(7195, 6, 'P178081148030', 'Profesional ', 'Wakil Kepala Sekolah', 'Teman Sejawat', 'Rekan guru sering terlihat membaca literatur, buku terbaru, atau membuka portal pendidikan (seperti PMM) untuk memperbarui pengetahuannya.', 0, 1.00, 0, 'angka', 100.00, 0.00, 1, '2026-06-07 05:51:20'),
(7196, 6, 'P178081148031', 'Profesional ', 'Wakil Kepala Sekolah', 'Teman Sejawat', 'Saat kami berdiskusi tentang materi pelajaran, rekan guru sangat menguasai konsep dan mampu menjelaskan hubungan materi dengan isu terkini.', 0, 1.00, 0, 'angka', 100.00, 0.00, 1, '2026-06-07 05:51:20');
INSERT INTO `perf_instrumen` (`id`, `periode_id`, `kode`, `kategori`, `target_jabatan`, `target_dinilai`, `pertanyaan`, `urutan`, `bobot`, `is_manual`, `tipe_jawaban`, `skor_ya`, `skor_tidak`, `status`, `created_at`) VALUES
(7197, 6, 'P178081148032', 'Profesional ', 'Wakil Kepala Sekolah', 'Teman Sejawat', 'Rekan guru mahir menggunakan aplikasi digital (Excel/E-Rapor/Canva) dan sering membantu rekan lain yang mengalami kesulitan teknis.', 0, 1.00, 0, 'angka', 100.00, 0.00, 1, '2026-06-07 05:51:20'),
(7198, 6, 'P178081148033', 'Profesional ', 'Wakil Kepala Sekolah', 'Teman Sejawat', 'Rekan guru aktif mengikuti webinar, workshop, atau pelatihan mandiri di luar jam sekolah secara rutin.', 0, 1.00, 0, 'angka', 100.00, 0.00, 1, '2026-06-07 05:51:20'),
(7199, 6, 'P178081148034', 'Profesional ', 'Wakil Kepala Sekolah', 'Teman Sejawat', 'Rekan guru sering berbagi \"tips\" atau \"rumus cepat\" dan metode baru yang ia temukan dari hasil pelatihannya kepada rekan sejawat.', 0, 1.00, 0, 'angka', 100.00, 0.00, 1, '2026-06-07 05:51:20'),
(7200, 6, 'P178081148035', 'Profesional ', 'Wakil Kepala Sekolah', 'Teman Sejawat', 'Rekan guru memahami juknis/aturan terbaru mengenai kurikulum dan mampu memberikan penjelasan jika rekan lain bertanya.', 0, 1.00, 0, 'angka', 100.00, 0.00, 1, '2026-06-07 05:51:20'),
(7201, 6, 'P178081148036', 'Profesional ', 'Wakil Kepala Sekolah', 'Teman Sejawat', 'Rekan guru terlihat produktif dalam menghasilkan karya, baik itu modul ajar, video pembelajaran, maupun tulisan ilmiah.', 0, 1.00, 0, 'angka', 100.00, 0.00, 1, '2026-06-07 05:51:20'),
(7202, 6, 'P178081148037', 'Profesional ', 'Wakil Kepala Sekolah', 'Teman Sejawat', 'Saat menghadapi masalah pembelajaran di kelasnya, rekan guru sering mengajak berdiskusi secara ilmiah untuk menemukan solusinya.', 0, 1.00, 0, 'angka', 100.00, 0.00, 1, '2026-06-07 05:51:20'),
(7203, 6, 'P178081148038', 'Profesional ', 'Wakil Kepala Sekolah', 'Teman Sejawat', 'Rekan guru mampu menghubungkan materi mata pelajarannya dengan mata pelajaran lain saat kami merancang proyek kolaborasi.', 0, 1.00, 0, 'angka', 100.00, 0.00, 1, '2026-06-07 05:51:20'),
(7204, 6, 'P178081148039', 'Profesional ', 'Wakil Kepala Sekolah', 'Teman Sejawat', 'Rekan guru memiliki visi ke depan untuk kemajuan sekolah dan sering mengusulkan ide-ide kreatif dalam pengembangan mutu pendidikan.', 0, 1.00, 0, 'angka', 100.00, 0.00, 1, '2026-06-07 05:51:20'),
(7205, 6, 'P17808126820', 'Kepribadian ', 'Kepala TU', 'Diri Sendiri', 'Saya hadir di sekolah dan sudah siap di meja kerja tepat waktu sebelum jam pelayanan operasional dimulai, meskipun tidak ada pengawasan langsung dari pimpinan.', 0, 1.00, 0, 'angka', 100.00, 0.00, 1, '2026-06-07 06:11:22'),
(7206, 6, 'P17808126821', 'Kepribadian ', 'Kepala TU', 'Diri Sendiri', 'Saya tetap menyelesaikan tugas-tugas administrasi yang mendesak hingga tuntas, meskipun waktu istirahat atau jam pulang sudah tiba.', 0, 1.00, 0, 'angka', 100.00, 0.00, 1, '2026-06-07 06:11:22'),
(7207, 6, 'P17808126822', 'Kepribadian ', 'Kepala TU', 'Diri Sendiri', 'Saya menjaga kerahasiaan dokumen pribadi guru, nilai siswa, atau data rahasia sekolah lainnya dan tidak membicarakannya kepada pihak luar.', 0, 1.00, 0, 'angka', 100.00, 0.00, 1, '2026-06-07 06:11:22'),
(7208, 6, 'P17808126823', 'Kepribadian ', 'Kepala TU', 'Diri Sendiri', 'Saya berani mengakui kesalahan input data secara jujur kepada pimpinan dan segera mencari solusi perbaikan tanpa menyalahkan sistem atau rekan lain.', 0, 1.00, 0, 'angka', 100.00, 0.00, 1, '2026-06-07 06:11:22'),
(7209, 6, 'P17808126824', 'Kepribadian ', 'Kepala TU', 'Diri Sendiri', 'Saya mampu mengendalikan emosi dan tetap bersikap profesional saat melayani warga sekolah, meskipun saya sedang berada dalam tekanan pekerjaan yang berat.', 0, 1.00, 0, 'angka', 100.00, 0.00, 1, '2026-06-07 06:11:22'),
(7210, 6, 'P17808126825', 'Kepribadian ', 'Kepala TU', 'Diri Sendiri', 'Saya mengenakan seragam dan atribut sekolah dengan rapi sesuai jadwal, sebagai bentuk rasa bangga dan profesionalisme terhadap profesi saya.', 0, 1.00, 0, 'angka', 100.00, 0.00, 1, '2026-06-07 06:11:22'),
(7211, 6, 'P17808126826', 'Kepribadian ', 'Kepala TU', 'Diri Sendiri', 'Saya mencatat setiap penggunaan barang inventaris kantor atau anggaran kecil secara transparan dan jujur agar dapat dipertanggungjawabkan.', 0, 1.00, 0, 'angka', 100.00, 0.00, 1, '2026-06-07 06:11:22'),
(7212, 6, 'P17808126827', 'Kepribadian ', 'Kepala TU', 'Diri Sendiri', 'Saya menerima saran atau kritik mengenai kualitas kerja saya dengan tangan terbuka dan berupaya memperbaikinya agar menjadi lebih baik.', 0, 1.00, 0, 'angka', 100.00, 0.00, 1, '2026-06-07 06:11:22'),
(7213, 6, 'P17808126828', 'Kepribadian ', 'Kepala TU', 'Diri Sendiri', 'Saya berinisiatif merapikan meja kerja, lemari arsip, dan peralatan kantor setiap hari agar suasana kerja tetap nyaman dan teratur.', 0, 1.00, 0, 'angka', 100.00, 0.00, 1, '2026-06-07 06:11:22'),
(7214, 6, 'P17808126829', 'Kepribadian ', 'Kepala TU', 'Diri Sendiri', 'Saya tetap berada di tempat tugas dan memberikan pelayanan hingga jam kerja berakhir, tanpa mencoba meninggalkan kantor lebih awal tanpa izin.', 0, 1.00, 0, 'angka', 100.00, 0.00, 1, '2026-06-07 06:11:22'),
(7215, 6, 'P178081268210', 'Sosial ', 'Kepala TU', 'Diri Sendiri', 'Saya menyambut dan mendengarkan keluhan orang tua siswa atau tamu dengan sabar serta tetap menggunakan tutur kata yang santun meskipun mereka sedang emosi.', 0, 1.00, 0, 'angka', 100.00, 0.00, 1, '2026-06-07 06:11:22'),
(7216, 6, 'P178081268211', 'Sosial ', 'Kepala TU', 'Diri Sendiri', 'Saya menawarkan bantuan kepada rekan kerja (guru atau sesama staf) jika melihat mereka sedang kewalahan mengerjakan tugas sekolah yang mendesak.', 0, 1.00, 0, 'angka', 100.00, 0.00, 1, '2026-06-07 06:11:22'),
(7217, 6, 'P178081268212', 'Sosial ', 'Kepala TU', 'Diri Sendiri', 'Saya menyapa dan berkomunikasi dengan sopan kepada seluruh warga sekolah tanpa membeda-bedakan status sosial mereka (guru, satpam, hingga petugas kebersihan).', 0, 1.00, 0, 'angka', 100.00, 0.00, 1, '2026-06-07 06:11:22'),
(7218, 6, 'P178081268213', 'Sosial ', 'Kepala TU', 'Diri Sendiri', 'Saya memilih untuk mendiskusikan masalah pekerjaan secara langsung dengan rekan sejawat jika terjadi kesalahpahaman, guna menghindari konflik di ruang kantor.', 0, 1.00, 0, 'angka', 100.00, 0.00, 1, '2026-06-07 06:11:22'),
(7219, 6, 'P178081268214', 'Sosial ', 'Kepala TU', 'Diri Sendiri', 'Saya memberikan informasi atau instruksi administratif kepada siswa dan guru dengan bahasa yang sederhana agar mereka mudah memahami alurnya.', 0, 1.00, 0, 'angka', 100.00, 0.00, 1, '2026-06-07 06:11:22'),
(7220, 6, 'P178081268215', 'Sosial ', 'Kepala TU', 'Diri Sendiri', 'Saya dengan senang hati membimbing rekan kerja yang kurang paham mengenai prosedur administrasi tertentu hingga urusan mereka selesai dengan baik.', 0, 1.00, 0, 'angka', 100.00, 0.00, 1, '2026-06-07 06:11:22'),
(7221, 6, 'P178081268216', 'Sosial ', 'Kepala TU', 'Diri Sendiri', 'Saya turut berpartisipasi dalam kegiatan sosial yang diadakan sekolah (seperti menjenguk rekan yang sakit atau bakti sosial) sebagai wujud kepedulian.', 0, 1.00, 0, 'angka', 100.00, 0.00, 1, '2026-06-07 06:11:22'),
(7222, 6, 'P178081268217', 'Sosial ', 'Kepala TU', 'Diri Sendiri', 'Saya segera menginformasikan setiap ada perubahan aturan atau alur layanan kepada pihak terkait agar tidak terjadi kebingungan di lingkungan sekolah.', 0, 1.00, 0, 'angka', 100.00, 0.00, 1, '2026-06-07 06:11:22'),
(7223, 6, 'P178081268218', 'Sosial ', 'Kepala TU', 'Diri Sendiri', 'Saya mampu menyesuaikan gaya komunikasi saya saat bekerja dengan berbagai rekan yang memiliki karakter dan kepribadian yang berbeda-beda.', 0, 1.00, 0, 'angka', 100.00, 0.00, 1, '2026-06-07 06:11:22'),
(7224, 6, 'P178081268219', 'Sosial ', 'Kepala TU', 'Diri Sendiri', 'Saya berupaya menjaga suasana kantor tetap positif dan ceria agar rekan kerja lainnya merasa nyaman saat berkoordinasi dengan bagian Tata Usaha.', 0, 1.00, 0, 'angka', 100.00, 0.00, 1, '2026-06-07 06:11:22'),
(7225, 6, 'P178081268220', 'Teknis ', 'Kepala TU', 'Diri Sendiri', 'Saya merapikan arsip surat dan dokumen sekolah dengan sistem tertentu sehingga saya bisa menemukannya dalam waktu singkat saat diminta pimpinan.', 0, 1.00, 0, 'angka', 100.00, 0.00, 1, '2026-06-07 06:11:22'),
(7226, 6, 'P178081268221', 'Teknis ', 'Kepala TU', 'Diri Sendiri', 'Saya secara mandiri mempelajari fitur-fitur baru pada aplikasi sekolah (seperti Dapodik atau e-Rapor) agar penginputan data tidak mengalami keterlambatan.', 0, 1.00, 0, 'angka', 100.00, 0.00, 1, '2026-06-07 06:11:22'),
(7227, 6, 'P178081268222', 'Teknis ', 'Kepala TU', 'Diri Sendiri', 'Saya memeriksa ulang setiap draf surat dinas atau laporan yang saya buat untuk memastikan tidak ada kesalahan ketik (typo) atau format yang salah.', 0, 1.00, 0, 'angka', 100.00, 0.00, 1, '2026-06-07 06:11:22'),
(7228, 6, 'P178081268223', 'Teknis ', 'Kepala TU', 'Diri Sendiri', 'Saya berupaya memperbaiki sendiri gangguan ringan pada perangkat kantor (seperti kertas printer macet) sebelum memutuskan untuk memanggil teknisi.', 0, 1.00, 0, 'angka', 100.00, 0.00, 1, '2026-06-07 06:11:22'),
(7229, 6, 'P178081268224', 'Teknis ', 'Kepala TU', 'Diri Sendiri', 'Saya memanfaatkan penyimpanan digital (seperti Google Drive) untuk menyimpan salinan dokumen penting agar data sekolah tetap aman dan mudah diakses.', 0, 1.00, 0, 'angka', 100.00, 0.00, 1, '2026-06-07 06:11:22'),
(7230, 6, 'P178081268225', 'Teknis ', 'Kepala TU', 'Diri Sendiri', 'Saya mampu menyusun data siswa atau laporan inventaris dalam bentuk tabel yang rapi sehingga memudahkan pimpinan dalam membaca data tersebut.', 0, 1.00, 0, 'angka', 100.00, 0.00, 1, '2026-06-07 06:11:22'),
(7231, 6, 'P178081268226', 'Teknis ', 'Kepala TU', 'Diri Sendiri', 'Saya mencatat setiap nomor agenda surat masuk dan keluar secara tertib agar tidak ada dokumen yang hilang atau tidak terdeteksi keberadaannya.', 0, 1.00, 0, 'angka', 100.00, 0.00, 1, '2026-06-07 06:11:22'),
(7232, 6, 'P178081268227', 'Teknis ', 'Kepala TU', 'Diri Sendiri', 'Saya selalu memantau ketersediaan stok alat tulis kantor (tinta, kertas, dll) dan segera mengajukan pengadaan sebelum stok tersebut habis total.', 0, 1.00, 0, 'angka', 100.00, 0.00, 1, '2026-06-07 06:11:22'),
(7233, 6, 'P178081268228', 'Teknis ', 'Kepala TU', 'Diri Sendiri', 'Saya merawat dan menggunakan perangkat kantor (fotokopi/scanner) dengan hati-hati sesuai prosedur agar alat tersebut tidak cepat rusak.', 0, 1.00, 0, 'angka', 100.00, 0.00, 1, '2026-06-07 06:11:22'),
(7234, 6, 'P178081268229', 'Teknis ', 'Kepala TU', 'Diri Sendiri', 'Saya melakukan pencadangan (backup) data administrasi secara rutin agar informasi sekolah tetap selamat jika sewaktu-waktu komputer mengalami gangguan.', 0, 1.00, 0, 'angka', 100.00, 0.00, 1, '2026-06-07 06:11:22'),
(7235, 6, 'P17808127530', 'Kepribadian', 'Pustakawan', 'Diri Sendiri', 'Meskipun tidak ada siswa yang berkunjung di pagi hari, saya secara konsisten hadir dan membuka pintu perpustakaan tepat waktu agar guru bisa mengambil referensi awal.', 0, 1.00, 0, 'angka', 100.00, 0.00, 1, '2026-06-07 06:12:33'),
(7236, 6, 'P17808127531', 'Kepribadian', 'Pustakawan', 'Diri Sendiri', 'Saat ditemukan adanya ketidaksesuaian jumlah buku antara data komputer dan rak, saya secara jujur melaporkannya dan melakukan penelusuran mandiri hingga tuntas.', 0, 1.00, 0, 'angka', 100.00, 0.00, 1, '2026-06-07 06:12:33'),
(7237, 6, 'P17808127532', 'Kepribadian', 'Pustakawan', 'Diri Sendiri', 'saya tetap tenang dan memberikan teguran yang mendidik saat menghadapi sekelompok siswa yang membuat gaduh dan mengganggu ketenangan ruang baca.', 0, 1.00, 0, 'angka', 100.00, 0.00, 1, '2026-06-07 06:12:33'),
(7238, 6, 'P17808127533', 'Kepribadian', 'Pustakawan', 'Diri Sendiri', 'Ketika ada koleksi buku langka atau mahal yang rusak, saya menunjukkan tanggung jawab dengan segera melakukan tindakan perbaikan (restorasi) agar dapat digunakan kembali.', 0, 1.00, 0, 'angka', 100.00, 0.00, 1, '2026-06-07 06:12:33'),
(7239, 6, 'P17808127534', 'Kepribadian', 'Pustakawan', 'Diri Sendiri', 'saya menunjukkan etika berpakaian yang sangat rapi dan santun, serta sering terlihat membaca buku saat sedang luang sebagai teladan bagi siswa.', 0, 1.00, 0, 'angka', 100.00, 0.00, 1, '2026-06-07 06:12:33'),
(7240, 6, 'P17808127535', 'Kepribadian', 'Pustakawan', 'Diri Sendiri', 'Saat terjadi lonjakan pengunjung yang sangat ramai, saya mampu mengatur antrean layanan sirkulasi dengan sabar tanpa terlihat emosional.', 0, 1.00, 0, 'angka', 100.00, 0.00, 1, '2026-06-07 06:12:33'),
(7241, 6, 'P17808127536', 'Kepribadian', 'Pustakawan', 'Diri Sendiri', 'saya secara rutin merapikan tata letak kursi dan meja perpustakaan setelah jam pulang sekolah tanpa harus menunggu instruksi dari pimpinan.', 0, 1.00, 0, 'angka', 100.00, 0.00, 1, '2026-06-07 06:12:33'),
(7242, 6, 'P17808127537', 'Kepribadian', 'Pustakawan', 'Diri Sendiri', 'Ketika mendapatkan saran dari Kepala Sekolah mengenai penataan ruang yang kurang nyaman, saya merespons dengan melakukan perubahan dekorasi yang inovatif.', 0, 1.00, 0, 'angka', 100.00, 0.00, 1, '2026-06-07 06:12:33'),
(7243, 6, 'P17808127538', 'Kepribadian', 'Pustakawan', 'Diri Sendiri', 'saya menjunjung tinggi integritas dengan tidak membiarkan fasilitas komputer atau printer perpustakaan digunakan untuk urusan di luar kebutuhan sekolah.', 0, 1.00, 0, 'angka', 100.00, 0.00, 1, '2026-06-07 06:12:33'),
(7244, 6, 'P17808127539', 'Kepribadian', 'Pustakawan', 'Diri Sendiri', 'saya tetap setia berada di area perpustakaan untuk memberikan layanan hingga menit terakhir jam operasional sekolah berakhir.', 0, 1.00, 0, 'angka', 100.00, 0.00, 1, '2026-06-07 06:12:33'),
(7245, 6, 'P178081275310', 'Sosial', 'Pustakawan', 'Diri Sendiri', 'Saat ada tamu dinas atau orang tua siswa berkunjung, saya menyambut mereka dengan ramah dan mampu menjelaskan keunggulan koleksi perpustakaan dengan baik.', 0, 1.00, 0, 'angka', 100.00, 0.00, 1, '2026-06-07 06:12:33'),
(7246, 6, 'P178081275311', 'Sosial', 'Pustakawan', 'Diri Sendiri', 'Ketika ada guru mata pelajaran yang membutuhkan referensi khusus untuk materi esok hari, saya secara aktif membantu mencarikan buku yang paling relevan.', 0, 1.00, 0, 'angka', 100.00, 0.00, 1, '2026-06-07 06:12:33'),
(7247, 6, 'P178081275312', 'Sosial', 'Pustakawan', 'Diri Sendiri', 'saya berinisiatif mendatangi siswa di kelas atau saat istirahat untuk mempromosikan buku-buku baru yang sesuai dengan minat mereka.', 0, 1.00, 0, 'angka', 100.00, 0.00, 1, '2026-06-07 06:12:33'),
(7248, 6, 'P178081275313', 'Sosial', 'Pustakawan', 'Diri Sendiri', 'Dalam memberikan layanan peminjaman, saya bersikap sangat adil dan tidak memberikan keistimewaan (seperti tambahan waktu pinjam) hanya kepada siswa tertentu.', 0, 1.00, 0, 'angka', 100.00, 0.00, 1, '2026-06-07 06:12:33'),
(7249, 6, 'P178081275314', 'Sosial', 'Pustakawan', 'Diri Sendiri', 'saya mampu menjelaskan aturan denda atau kehilangan buku dengan bahasa yang tenang sehingga tidak menimbulkan konflik dengan siswa atau orang tua.', 0, 1.00, 0, 'angka', 100.00, 0.00, 1, '2026-06-07 06:12:33'),
(7250, 6, 'P178081275315', 'Sosial', 'Pustakawan', 'Diri Sendiri', 'Saat sekolah mengadakan acara besar di luar perpustakaan, saya secara sukarela membantu tim kerja lainnya agar acara tersebut sukses.', 0, 1.00, 0, 'angka', 100.00, 0.00, 1, '2026-06-07 06:12:33'),
(7251, 6, 'P178081275316', 'Sosial', 'Pustakawan', 'Diri Sendiri', 'saya menjalin komunikasi aktif dengan perpustakaan luar atau komunitas literasi untuk menambah wawasan pengembangan perpustakaan sekolah.', 0, 1.00, 0, 'angka', 100.00, 0.00, 1, '2026-06-07 06:12:33'),
(7252, 6, 'P178081275317', 'Sosial', 'Pustakawan', 'Diri Sendiri', 'Ketika ada siswa yang mengeluh karena buku yang dicari tidak tersedia, saya mendengarkan dengan empati dan menawarkan opsi buku lain yang serupa.', 0, 1.00, 0, 'angka', 100.00, 0.00, 1, '2026-06-07 06:12:33'),
